-- ───────────────────────────── Section 2: hand-written invariants ─────────────────────────────

-- Partial unique indexes (not expressible in Prisma schema)
-- VoiceProfile: at most one active version per user (data-model.md §2.2).
CREATE UNIQUE INDEX "voice_profiles_user_id_active_key" ON "voice_profiles"("user_id") WHERE "is_active";
-- I7: at most one PENDING schedule per draft.
CREATE UNIQUE INDEX "schedules_draft_id_pending_key" ON "schedules"("draft_id") WHERE "status" = 'PENDING';
-- I8: never two posts of the same draft — one Publication IN_PROGRESS, SUCCEEDED or AMBIGUOUS per draft
-- (an ambiguous outcome blocks a second attempt until reconciled, ADR-0003 §5-6).
CREATE UNIQUE INDEX "publications_draft_id_active_key" ON "publications"("draft_id") WHERE "status" IN ('IN_PROGRESS', 'SUCCEEDED', 'AMBIGUOUS');

-- CHECK constraints
-- I5: automatic approvals carry a reason and the policy that authorized them.
ALTER TABLE "approvals" ADD CONSTRAINT "approvals_system_requires_reason_and_policy_check"
  CHECK ("actor_type" <> 'SYSTEM' OR ("reason" IS NOT NULL AND "policy_snapshot" IS NOT NULL));
-- Human approvals identify the human (contracts `ApprovalSchema` refinement).
ALTER TABLE "approvals" ADD CONSTRAINT "approvals_user_requires_actor_check"
  CHECK ("actor_type" <> 'USER' OR "actor_user_id" IS NOT NULL);
-- Encrypted-at-rest envelopes are all-or-none (ADR-0004 framing; cipher itself lands in T-052).
ALTER TABLE "users" ADD CONSTRAINT "users_totp_envelope_all_or_none_check"
  CHECK (("totp_secret_ciphertext" IS NULL) = ("totp_wrapped_dek" IS NULL)
     AND ("totp_secret_ciphertext" IS NULL) = ("totp_key_version" IS NULL));
ALTER TABLE "oauth_states" ADD CONSTRAINT "oauth_states_code_verifier_all_or_none_check"
  CHECK (("code_verifier_ciphertext" IS NULL) = ("code_verifier_key_version" IS NULL));
-- I12: collected content is always untrusted; the flag is a constant.
ALTER TABLE "source_items" ADD CONSTRAINT "source_items_untrusted_check" CHECK ("untrusted");
-- Source fetch interval minimum (data-model.md §2.3, contracts SOURCE_MIN_FETCH_INTERVAL_MINUTES).
ALTER TABLE "sources" ADD CONSTRAINT "sources_fetch_interval_minutes_check" CHECK ("fetch_interval_minutes" >= 60);
-- I1 support: rank 1..5 inside a run; score 0..100.
ALTER TABLE "opportunities" ADD CONSTRAINT "opportunities_rank_range_check" CHECK ("rank" IS NULL OR "rank" BETWEEN 1 AND 5);
ALTER TABLE "opportunities" ADD CONSTRAINT "opportunities_score_range_check" CHECK ("score" >= 0 AND "score" <= 100);
ALTER TABLE "draft_versions" ADD CONSTRAINT "draft_versions_version_number_check" CHECK ("version_number" >= 1);
-- Autopilot modes require a minimum score (contracts `AutonomySettingsSchema` refinement).
ALTER TABLE "autonomy_settings" ADD CONSTRAINT "autonomy_settings_autopilot_requires_score_check"
  CHECK ("mode" = 'ASSISTED' OR "auto_approve_min_score" IS NOT NULL);
-- I6: timezone is NOT NULL by schema; also never blank.
ALTER TABLE "schedules" ADD CONSTRAINT "schedules_timezone_not_blank_check" CHECK (length(btrim("timezone")) > 0);
ALTER TABLE "curation_runs" ADD CONSTRAINT "curation_runs_timezone_not_blank_check" CHECK (length(btrim("timezone")) > 0);

-- Append-only tables (I3 draft_versions, approvals; I11 audit_events): INSERT only.
-- Enforced here by trigger; the runtime database role additionally loses UPDATE/DELETE privileges
-- when the roles are provisioned (ADR-0004 §9, Estaleiro/T-052).
CREATE FUNCTION "reject_append_only_mutation"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'table % is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'P0001', HINT = 'Insert a new row instead (data-model.md I3/I11).';
END;
$$;

CREATE TRIGGER "draft_versions_append_only" BEFORE UPDATE OR DELETE ON "draft_versions"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_mutation"();
CREATE TRIGGER "draft_versions_append_only_truncate" BEFORE TRUNCATE ON "draft_versions"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_mutation"();

CREATE TRIGGER "approvals_append_only" BEFORE UPDATE OR DELETE ON "approvals"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_mutation"();
CREATE TRIGGER "approvals_append_only_truncate" BEFORE TRUNCATE ON "approvals"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_mutation"();

CREATE TRIGGER "audit_events_append_only" BEFORE UPDATE OR DELETE ON "audit_events"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_mutation"();
CREATE TRIGGER "audit_events_append_only_truncate" BEFORE TRUNCATE ON "audit_events"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_mutation"();
